export type ParsedClientCancelReservationInstruction<
  TProgram extends string = typeof PACTUM_ESCROW_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    clientAuthority: TAccountMetas[0];
    escrowConfig: TAccountMetas[1];
    globalConfig: TAccountMetas[2];
    client: TAccountMetas[3];
    provider: TAccountMetas[4];
    integrator?: TAccountMetas[5] | undefined;
    bookingDays: TAccountMetas[6];
    reservation: TAccountMetas[7];
    escrowVault: TAccountMetas[8];
    platformVault: TAccountMetas[9];
    clientTokenAccount: TAccountMetas[10];
    providerTokenAccount: TAccountMetas[11];
    integratorTokenAccount?: TAccountMetas[12] | undefined;
    usdcMint: TAccountMetas[13];
    rentPayer: TAccountMetas[14];
    cpiAuthority: TAccountMetas[15];
    coreProgram: TAccountMetas[16];
    tokenProgram: TAccountMetas[17];
  };
  data: ClientCancelReservationInstructionData;
};

export function parseClientCancelReservationInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClientCancelReservationInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 18) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 18,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === PACTUM_ESCROW_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      clientAuthority: getNextAccount(),
      escrowConfig: getNextAccount(),
      globalConfig: getNextAccount(),
      client: getNextAccount(),
      provider: getNextAccount(),
      integrator: getNextOptionalAccount(),
      bookingDays: getNextAccount(),
      reservation: getNextAccount(),
      escrowVault: getNextAccount(),
      platformVault: getNextAccount(),
      clientTokenAccount: getNextAccount(),
      providerTokenAccount: getNextAccount(),
      integratorTokenAccount: getNextOptionalAccount(),
      usdcMint: getNextAccount(),
      rentPayer: getNextAccount(),
      cpiAuthority: getNextAccount(),
      coreProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getClientCancelReservationInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
